input.command:
cd books/go-service-design
for f in value-objects aggregate-invariants domain-events anti-corruption-layer module-structure; do
  awk -v file="$f" '
    /^```/ {incode=!incode; next}
    incode {next}
    /^[|>#]/ {next}
    /^\s*$/ {next}
    {
      line=$0
      n=split(line, sentences, "。")
      for(i=1;i<n;i++){
        s=sentences[i]
        # 全角文字数を概算（バイト数/3 + 半角）
        len=length(s)
        if(len>=75){ printf "%s L%d (%d字): %s。\n", file, NR, len, s }
      }
    }
  ' "$f.md"
done 2>&1 | head -40
